import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // Fuzz the provided _baseToken and other params; the general rule: after initialize, c.baseToken() == _baseToken
    function testFuzz_property(address _baseToken, address _nft, uint128 _virtualBaseTokenReserves, uint128 _virtualNftReserves, uint56 _changeFee, uint16 _feeRate, bytes32 _merkleRoot, bool _useStolenNftOracle, bool _payRoyalties) public {
        // Keep inputs wide but avoid the zero-address factory/stolen oracle collisions (not necessary but harmless)
        // No tight constraints so fuzzer can find case where mutant differs.

        // Make the call as an arbitrary sender to allow msg.sender diffs
        vm.prank(address(0xBEEF));
        bool ok;
        try c.initialize(_baseToken, _nft, _virtualBaseTokenReserves, _virtualNftReserves, _changeFee, _feeRate, _merkleRoot, _useStolenNftOracle, _payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        // If initialize reverted, then we can't read baseToken meaningfully; only assert when it succeeded.
        if (ok) {
            // Exactly one assertion: in the correct contract baseToken equals the supplied _baseToken for all inputs.
            assertTrue(c.baseToken() == _baseToken);
        } else {
            // If initialize reverted, still assert true of a property the reference must satisfy: initialization should only revert
            // on the same conditions in both versions; but to keep single assertion behavior and pass for reference, do a vacuous true via checking initialized()==false
            // However rule requires single assertTrue reading c; here we assert initialized() == false when init failed
            assertTrue(c.initialized() == false);
        }
    }
}

