contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // Fuzz: the deciding parameter is the candidate baseToken address to initialize with.
    // General rule: after any successful initialize(...) call, c.baseToken() == _baseToken.
    // The mutant breaks this for some _baseToken (fuzzer will find one).
    function testFuzz_property(address baseTokenAddr) public {
        // keep wide domain but exclude address(0) only to ensure both zero and non-zero are allowed
        // We do not exclude address(0) because the property must hold for all inputs; include it.

        // Other parameters: pick reasonable arbitrary values; they are not the deciding factor but must be fuzz-independent.
        address nft = address(0x1234);
        uint128 vBase = 1e18;
        uint128 vNft = 1e18;
        uint56 changeFee = 1;
        uint16 feeRate = 100;
        bytes32 merkleRoot = bytes32(0);
        bool useStolen = false;
        bool payRoyalties = false;

        bool ok;
        try c.initialize(baseTokenAddr, nft, vBase, vNft, changeFee, feeRate, merkleRoot, useStolen, payRoyalties) {
            ok = true;
        } catch {
            // If initialize reverts, we treat as failure to initialize; property only requires that when initialize returns successfully,
            // baseToken equals the provided address. So in revert case we consider ok=false and assert not on baseToken.
            ok = false;
        }

        // Exactly one assertion: if initialization succeeded, then the contract's public baseToken must equal the provided one.
        if (ok) {
            assertTrue(c.baseToken() == baseTokenAddr);
        } else {
            // If initialize reverted, ensure only that it indeed reverted (no further assertion). We satisfy the single-assert rule by
            // asserting a trivially true statement about ok==false in the revert branch is not allowed; instead, we return early.
            // To adhere to the requirement of exactly one assertTrue in the test, we place it only in the success branch.
            // If init reverted, the test should not assert; but Foundry tests must have at least one assert in all runs — however
            // per problem rules, the single assert pertains to the reference vs mutant; here we keep it conditional only on ok.
            // To satisfy solidity syntax, just do nothing when ok==false.
            return;
        }
    }
}

