pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // fuzz _baseToken and a boolean that decides whether to call initialize as msg.sender or via a contract
    function testFuzz_property(address _baseToken, bool asContract) public {
        // keep fuzz wide but avoid the trivial zero-address for caller contract deployment address collision
        // (no tight assumptions so mutant can be found)

        // prepare parameters for initialize (use deterministic defaults for others)
        address nft = address(0x1234);
        uint128 vBase = 1000;
        uint128 vNft = 10;
        uint56 changeFee = 1;
        uint16 feeRate = 100;
        bytes32 merkleRoot = bytes32(0);
        bool useStolen = false;
        bool payRoyalties = false;

        bool ok;

        // We will call initialize either directly from this EOA or via a helper contract that simply forwards the call.
        // The mutant's bug manifests as baseToken being left as address(0) despite initialize appearing to succeed.
        if (!asContract) {
            // direct call from EOA
            try c.initialize(_baseToken, nft, vBase, vNft, changeFee, feeRate, merkleRoot, useStolen, payRoyalties) {
                ok = true;
            } catch {
                ok = false;
            }
        } else {
            // deploy a helper forwarder and call through it
            Forwarder f = new Forwarder();
            // call initialize via the forwarder
            try f.doInitialize(address(c), _baseToken, nft, vBase, vNft, changeFee, feeRate, merkleRoot, useStolen, payRoyalties) {
                ok = true;
            } catch {
                ok = false;
            }
        }

        // Single assertion: if initialize returned (ok==true), then c.baseToken() must equal the _baseToken argument.
        // This is a universal property the correct contract satisfies; the mutant violates it for some fuzzed inputs.
        if (ok) {
            assertTrue(c.baseToken() == _baseToken);
        } else {
            // if initialize reverted, then nothing to assert about baseToken — still satisfy single assertion requirement
            // we assert that initialize did indeed fail (i.e., ok == false) by checking a tautology that uses c (address)
            // but the test harness requires a single assertTrue overall; to keep exactly one assert we branch so only one is executed.
            assertTrue(!ok);
        }
    }
}

// helper that simply forwards the initialize call (to allow calling from a non-EOA)
contract Forwarder {
    function doInitialize(
        address target,
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) external {
        // forward the call and bubble up revert/success
        (bool success, bytes memory ret) = target.call(
            abi.encodeWithSignature("initialize(address,address,uint128,uint128,uint56,uint16,bytes32,bool,bool)",
                _baseToken,
                _nft,
                _virtualBaseTokenReserves,
                _virtualNftReserves,
                _changeFee,
                _feeRate,
                _merkleRoot,
                _useStolenNftOracle,
                _payRoyalties
            )
        );
        if (!success) {
            assembly { revert(add(ret, 32), mload(ret)) }
        }
    }
}

